import React, { useState, useMemo, useEffect } from 'react';
import './Board.css';
import { getValueFromCoordinates, getCoordinatesFromValue } from './coordinates.js';
import Ended from './Ended'; // Import komponenty Ended

const Board = ({ gameData, socket }) => {
  const gridSize = 11;
  const centerIndex = Math.floor(gridSize / 2);

  const { pieces: initialPieces } = gameData.board;
  const { players } = gameData;

  const [pieces, setPieces] = useState(initialPieces);
  const [error, setError] = useState(null);
  const [statusMessage, setStatusMessage] = useState("");
  const [selectedPiece, setSelectedPiece] = useState(null); // Přidání stavu pro vybranou figurku
  const [diceRoll, setDiceRoll] = useState(null); // Stav pro výsledek hodu kostkou
  const [gameEnded, setGameEnded] = useState(false); // Stav pro kontrolu, jestli hra skončila
  const [score, setScore] = useState([]); // Stav pro skóre hráčů
  const [houseLength, setHouseLength] = useState(0); // Stav pro délku domečku

  useEffect(() => {
    if (!socket) return;

    socket.on('connect', () => console.log('Socket connected: ', socket.id));
    socket.on('disconnect', () => console.log('Disconnected from server.'));

    socket.on('game:updated', (data) => {
      const { updatedPiece, nextPlayerId } = data;
      if (updatedPiece) {
        setPieces((prevPieces) =>
          prevPieces.map((piece) =>
            piece.ownerId === updatedPiece.ownerId && piece.color === updatedPiece.color
              ? { ...piece, commonPosition: updatedPiece.commonPosition }
              : piece
          )
        );
        if (nextPlayerId) setStatusMessage(`It's player ${nextPlayerId}'s turn.`);
      }
    });

    socket.on('game:diceRolled', (data) => {
      setDiceRoll(data.dice);
      setStatusMessage(`Player ${data.playerId} rolled a ${data.dice}.`);
      if (data.canDeploy) socket.emit('game:deployPiece');
    });

    socket.on('game:ended', (data) => {
      setGameEnded(true);
      setScore(data.score);
      setHouseLength(data.houseLength);
    });

    return () => {
      socket.off('game:updated');
      socket.off('game:diceRolled');
      socket.off('game:ended');
    };
  }, [socket]);

  const startNewGame = () => {
    setPieces(gameData.board.pieces);
    setScore([]);
    setHouseLength(0);
    setGameEnded(false);
    socket.emit('game:start');
  };

  const tileColorMap = useMemo(() => {
    const colorMap = new Map();
    players.forEach((player, index) => {
      const tiles = index === 0
        ? [[4, 0], [5, 1], [5, 2], [5, 3], [5, 4], [0, 0], [0, 1], [1, 0], [1, 1]]
        : index === 1
        ? [[0, 6], [1, 5], [2, 5], [3, 5], [4, 5], [0, 9], [0, 10], [1, 9], [1, 10]]
        : index === 2
        ? [[6, 10], [5, 6], [5, 7], [5, 8], [5, 9], [9, 9], [10, 9], [9, 10], [10, 10]]
        : [[10, 4], [6, 5], [7, 5], [8, 5], [9, 5], [9, 0], [9, 1], [10, 0], [10, 1]];
      tiles.forEach(([row, col]) => colorMap.set(`${row}-${col}`, player.color));
    });
    return colorMap;
  }, [players]);

  const pieceMap = useMemo(() => {
    const map = new Map();
    pieces.forEach((piece) => {
      const { row, col } = getCoordinatesFromValue(piece.commonPosition, piece.color);
      map.set(`${row}-${col}`, piece);
    });
    return map;
  }, [pieces]);

  const getTileColor = (row, col) => {
    if (!((row >= centerIndex - 1 && row <= centerIndex + 1) || (col >= centerIndex - 1 && col <= centerIndex + 1))) {
      return 'white';
    }
    return tileColorMap.get(`${row}-${col}`) || 'white';
  };

  const renderPiece = (row, col) => {
    const piece = pieceMap.get(`${row}-${col}`);
    if (piece) {
      const isSelected = selectedPiece === piece;
      return (
        <div
          className={`piece ${isSelected ? 'selected-piece' : ''}`}
          style={{
            backgroundColor: piece.color,
            border: isSelected ? '2px solid black' : 'none',
            width: '70%',
            height: '70%',
          }}
        />
      );
    }
    return null;
  };

  const handleTileClick = (row, col) => {
    const clickedPiece = pieceMap.get(`${row}-${col}`);
    if (selectedPiece) {
      const newPosition = getValueFromCoordinates(row, col, selectedPiece.color);
      setError(null);
      socket.emit('game:movePiece', { commonPosition: newPosition });
      setSelectedPiece(null);
    } else if (clickedPiece) {
      setSelectedPiece(clickedPiece);
      setError(null);
      setStatusMessage('Piece selected.');
    } else {
      setError('Invalid move. No piece selected.');
    }
  };

  const rollDice = () => socket?.emit('game:play');

  return (
    <div className="board-container">
      {gameEnded ? (
        <Ended score={score} houseLength={houseLength} onNewGame={startNewGame} />
      ) : (
        <>
          {statusMessage && <div className="status-message">{statusMessage}</div>}
          {error && <div className="error">{error}</div>}
          <div className="board">
            {Array.from({ length: gridSize }).map((_, row) => (
              <div key={row} className="board-row">
                {Array.from({ length: gridSize }).map((_, col) => (
                  <div
                    key={`${row}-${col}`}
                    className={`tile ${getTileColor(row, col) === 'white' ? 'empty-tile' : ''}`}
                    style={{ backgroundColor: getTileColor(row, col) }}
                    onClick={() => handleTileClick(row, col)}
                  >
                    {renderPiece(row, col)}
                  </div>
                ))}
              </div>
            ))}
          </div>
          <button onClick={rollDice} className="roll-dice-button">Roll Dice</button>
        </>
      )}
    </div>
  );
};

export default Board;
